const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const dallasport = ee.Geometry.Point([-123.7, 46.3]); // Dallasport, WA approximate coordinates
  const medford = ee.Geometry.Point([-122.9, 42.3]); // Medford, OR approximate coordinates
  const regions = ee.FeatureCollection([ee.Feature(dallasport, {name: 'Dallasport'}), ee.Feature(medford, {name: 'Medford'})]);

  // Time period - focusing on recent years with known heatwaves
  const startDate = '2020-01-01';
  const endDate = '2023-12-31';

  // Get ERA5-Land temperature data
  const tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .select('temperature_2m');

  // Check collection size
  const collectionSize = tempCollection.size().getInfo();
  console.log(`ERA5 Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Convert temperature from Kelvin to Fahrenheit and find max
  const maxTempF = tempCollection.map(function(image) {
    const tempK = image.select('temperature_2m');
    const tempF = tempK.subtract(273.15).multiply(9/5).add(32);
    return tempF.rename('temperature_2m_f');
  }).max();

  // Calculate max temperature for each location
  const dallasportMax = maxTempF.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: dallasport,
    scale: 1000,
    maxPixels: 1e9
  }).get('temperature_2m_f');

  const medfordMax = maxTempF.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: medford,
    scale: 1000,
    maxPixels: 1e9
  }).get('temperature_2m_f');

  // Get values
  const dallasportVal = dallasportMax.getInfo();
  const medfordVal = medfordMax.getInfo();

  console.log(`Dallasport Max Temp: ${dallasportVal ? dallasportVal.toFixed(1) : 'N/A'}°F`);
  console.log(`Medford Max Temp: ${medfordVal ? medfordVal.toFixed(1) : 'N/A'}°F`);

  // Validation checks
  if (dallasportVal === null || medfordVal === null || 
      isNaN(dallasportVal) || isNaN(medfordVal)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if either location exceeded 105°F
  const dallasportAbove105 = dallasportVal > 105;
  const medfordAbove105 = medfordVal > 105;

  console.log(`Dallasport >105°F: ${dallasportAbove105}`);
  console.log(`Medford >105°F: ${medfordAbove105}`);

  // Final answer
  if (dallasportAbove105 || medfordAbove105) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
